/**
 * 图片压缩工具 - Canvas API 实现
 */

/**
 * 压缩图片为 base64
 * @param {File} file - 文件对象
 * @param {number} maxWidth - 最大宽度，默认 800
 * @param {number} quality - 压缩质量，默认 0.6
 * @returns {Promise<string>} base64 字符串
 */
export function compressImage(file, maxWidth = 800, quality = 0.6) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = (e) => {
      const img = new Image()
      img.onload = () => {
        const canvas = document.createElement('canvas')
        let { width, height } = img

        // 等比缩放
        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width)
          width = maxWidth
        }

        canvas.width = width
        canvas.height = height

        const ctx = canvas.getContext('2d')
        ctx.drawImage(img, 0, 0, width, height)

        // 尝试 JPEG，更小；Fallback PNG
        let dataUrl = canvas.toDataURL('image/jpeg', quality)
        // 如果 base64 太大，再压一次
        if (dataUrl.length > 500 * 1024) {
          dataUrl = canvas.toDataURL('image/jpeg', 0.3)
        }

        resolve(dataUrl)
      }
      img.onerror = (err) => reject(new Error('图片加载失败'))
      img.src = e.target.result
    }
    reader.onerror = () => reject(new Error('文件读取失败'))
    reader.readAsDataURL(file)
  })
}

/**
 * 压缩多个图片
 * @param {File[]} files - 文件数组
 * @param {number} maxWidth - 最大宽度
 * @param {number} quality - 压缩质量
 * @returns {Promise<string[]>} base64 数组
 */
export async function compressImages(files, maxWidth = 800, quality = 0.6) {
  const results = []
  for (const file of files) {
    if (!file.type.startsWith('image/')) continue
    const base64 = await compressImage(file, maxWidth, quality)
    results.push(base64)
  }
  return results
}

/**
 * 从 base64 数据中提取格式
 */
export function getBase64Mime(base64) {
  const match = base64.match(/^data:([^;]+);/)
  return match ? match[1] : 'image/jpeg'
}

/**
 * base64 字符串大小估算（字节数）
 */
export function getBase64Size(base64) {
  if (!base64) return 0
  // 去掉头部 "data:...;base64," 后估算
  const raw = base64.replace(/^data:[^;]+;base64,/, '')
  return Math.round((raw.length * 3) / 4)
}
