=\"9999999\"\n          :precision=\"2\"\n          controls-position=\"right\"\n          style=\"width: 100%\"\n          placeholder=\"请输入价格\"\n        />\n      </el-form-item>\n\n      <!-- 存放地点 -->\n      <el-form-item label=\"存放地点\">\n        <el-autocomplete\n          v-model=\"form.location\"\n          :fetch-suggestions=\"queryLocation\"\n          placeholder=\"如：卧室衣柜、冰箱\"\n          style=\"width: 100%\"\n          clearable\n        />\n      </el-form-item>\n\n      <!-- 购买日期 -->\n      <el-form-item label=\"购买日期\" prop=\"purchaseDate\">\n        <el-date-picker\n          v-model=\"form.purchaseDate\"\n          type=\"date\"\n          placeholder=\"选择购买日期\"\n          style=\"width: 100%\"\n          :picker-options=\"purchaseDatePicker\"\n          format=\"yyyy-MM-dd\"\n          value-format=\"yyyy-MM-dd\"\n        />\n      </el-form-item>\n\n      <!-- 过期时间 -->\n      <el-form-item label=\"过期时间\" prop=\"expiryDate\">\n        <el-date-picker\n          v-model=\"form.expiryDate\"\n          type=\"date\"\n          placeholder=\"选择过期时间\"\n          style=\"width: 100%\"\n          format=\"yyyy-MM-dd\"\n          value-format=\"yyyy-MM-dd\"\n        />\n      </el-form-item>\n\n      <!-- 备注 -->\n      <el-form-item label=\"备注\">\n        <el-input\n          v-model=\"form.remark\"\n          type=\"textarea\"\n          :rows=\"3\"\n          placeholder=\"记录价格、购买渠道、使用注意事项等\"\n          maxlength=\"200\"\n          show-word-limit\n        />\n      </el-form-item>\n\n      <!-- 照片 -->\n      <el-form-item label=\"照片 (最多3张)\">\n        <div class=\"photo-section\">\n          <!-- 已选照片 -->\n          <div class=\"photo-list\">\n            <div\n              v-for=\"(photo, idx) in form.photos\"\n              :key=\"idx\"\n              class=\"photo-item\"\n            >\n              <img :src=\"photo\" class=\"photo-thumb\" @click=\"previewPhoto(idx)\" />\n              <span class=\"photo-del\" @click=\"removePhoto(idx)\">×</span>\n            </div>\n            <!-- 添加按钮 -->\n            <div v-if=\"form.photos.length < 3\" class=\"photo-add\" @click=\"showPhotoMenu\">\n              <span>+ 添加照片</span>\n            </div>\n          </div>\n        </div>\n      </el-form-item>\n\n      <!-- 删除按钮（编辑时） -->\n      <div v-if=\"isEdit\" class=\"delete-section\">\n        <el-button\n          type=\"danger\"\n          plain\n          style=\"width: 100%\"\n          @click=\"deleteItem\"\n        >\n          删除物品\n        </el-button>\n      </div>\n    </el-form>\n\n    <!-- 照片来源选择弹窗 -->\n    <el-dialog\n      title=\"选择图片来源\"\n      :visible.sync=\"photoDialogVisible\"\n      width=\"280px\"\n      :close-on-click-modal=\"true\"\n    >\n      <div class=\"photo-source-btns\">\n        <el-button\n          style=\"width: 100%\"\n          @click=\"openCamera\"\n        >\n          📷 拍照\n        </el-button>\n        <el-button\n          style=\"width: 100%; margin-top: 10px\"\n          @click=\"openGallery\"\n        >\n          🖼️ 从相册选择\n        </el-button>\n      </div>\n    </el-dialog>\n\n    <!-- 隐藏的文件输入框 -->\n    <input\n      ref=\"fileInput\"\n      type=\"file\"\n      accept=\"image/*\"\n      style=\"display: none\"\n      @change=\"onFileChange\"\n    />\n  </div>\n</template>\n\n<script>\nimport {\n  loadCategories,\n  addItem,\n  updateItem,\n  deleteItem,\n  getItemById,\n  getLocations\n} from '@/store/index'\nimport { compressImage } from '@/utils/compress'\n\nexport default {\n  name: 'ItemForm',\n  data() {\n    return {\n      isEdit: false,\n      itemId: null,\n      saving: false,\n      categories: [],\n      form: {\n        name: '',\n        typeId: '',\n        price: 0,\n        location: '',\n        purchaseDate: '',\n        expiryDate: '',\n        remark: '',\n        photos: []\n      },\n      rules: {\n        name: [{ required: true, message: '请输入物品名称', trigger: 'blur' }],\n        typeId: [{ required: true, message: '请选择分类', trigger: 'change' }],\n        purchaseDate: [{ required: true, message: '请选择购买日期', trigger: 'change' }],\n        expiryDate: []\n      },\n      purchaseDatePicker: {\n        disabledDate(date) {\n          return date.getTime() > Date.now()\n        }\n      },\n      photoDialogVisible: false,\n      fileSource: 'camera' // 'camera' or 'gallery'\n    }\n  },\n  created() {\n    this.loadData()\n  },\n  methods: {\n    loadData() {\n      this.categories = loadCategories()\n      this.itemId = this.$route.params.id\n      this.isEdit = !!this.itemId\n\n      if (this.isEdit) {\n        const item = getItemById(this.itemId)\n        if (item) {\n          this.form = {\n            name: item.name,\n            typeId: item.typeId,\n            price: item.price || 0,\n            location: item.location || '',\n            purchaseDate: item.purchaseDate || '',\n            expiryDate: item.expiryDate || '',\n            remark: item.remark || '',\n            photos: item.photos ? [...item.photos] : []\n          }\n        } else {\n          this.$message.error('物品不存在')\n          this.$router.replace('/add')\n        }\n      } else {\n        // 新增时重置\n        this.form = {\n          name: '',\n          typeId: this.categories[0] ? this.categories[0].id : '',\n          price: 0,\n          location: '',\n          purchaseDate: this.formatDate(new Date()),\n          expiryDate: '',\n          remark: '',\n          photos: []\n        }\n      }\n    },\n\n    formatDate(date) {\n      const d = new Date(date)\n      const y = d.getFullYear()\n      const m = String(d.getMonth() + 1).padStart(2, '0')\n      const day = String(d.getDate()).padStart(2, '0')\n      return `${y}-${m}-${day}`\n    },\n\n    queryLocation(queryString, cb) {\n      const locs = getLocations().map(l => ({ value: l }))\n      cb(locs.filter(l =>\n        l.value.toLowerCase().includes(queryString.toLowerCase())\n      ))\n    },\n\n    showPhotoMenu() {\n      this.photoDialogVisible = true\n    },\n\n    openCamera() {\n      this.photoDialogVisible = false\n      this.fileSource = 'camera'\n      const input = this.$refs.fileInput\n      input.removeAttribute('capture')\n      input.setAttribute('capture', 'environment')\n      input.value = ''\n      input.click()\n    },\n\n    openGallery() {\n      this.photoDialogVisible = false\n      this.fileSource = 'gallery'\n      const input = this.$refs.fileInput\n      input.removeAttribute('capture')\n      input.value = ''\n      input.click()\n    },\n\n    async onFileChange(e) {\n      const files = Array.from(e.target.files)\n      if (files.length === 0) return\n\n      const remaining = 3 - this.form.photos.length\n      if (remaining <= 0) {\n        this.$message.warning('最多只能添加3张照片')\n        return\n      }\n\n      this.$message.loading('处理中...', 0)\n\n      try {\n        const filesToProcess = files.slice(0, remaining)\n        const base64s = await Promise.all(\n          filesToProcess.map(f => compressImage(f))\n        )\n        this.form.photos.push(...base64s)\n        this.$message.closeLoading()\n        if (this.form.photos.length >= 3) {\n          this.$message.info('已达最大照片数量(3张)')\n        }\n      } catch (err) {\n        this.$message.closeLoading()\n        this.$message.error('图片处理失败')\n        console.error(err)\n      }\n\n      // 清空 input\n      e.target.value = ''\n    },\n\n    removePhoto(idx) {\n      this.form.photos.splice(idx, 1)\n    },\n\n    previewPhoto(idx) {\n      const urls = this.form.photos.map(p => ({ url: p }))\n      this.$imagePreview ? this.$imagePreview(urls, idx) : window.open(urls[idx].url)\n    },\n\n    goBack() {\n      this.$router.back()\n    },\n\n    async save() {\n      try {\n        await this.$refs.form.validate()\n      } catch (e) {\n        return\n      }\n\n      if (this.form.photos.length === 0) {\n        this.$message.warning('请至少上传一张照片')\n        return\n      }\n\n      this.saving = true\n\n      try {\n        if (this.isEdit) {\n          updateItem(this.itemId, { ...this.form })\n          this.$message.success('保存成功')\n        } else {\n          addItem({ ...this.form })\n          this.$message.success('添加成功')\n        }\n        this.$router.replace('/')\n      } catch (err) {\n        this.$message.error('保存失败')\n        console.error(err)\n      } finally {\n        this.saving = false\n      }\n    },\n\n    deleteItem() {\n      this.$confirm('确定要删除该物品吗？此操作不可撤销。', '删除物品', {\n        confirmButtonText: '删除',\n        cancelButtonText: '取消',\n        type: 'warning'\n      }).then(() => {\n        deleteItem(this.itemId)\n        this.$message.success('删除成功')\n        this.$router.replace('/')\n      }).catch(() => {})\n    }\n  }\n}\n</script>\n\n<style scoped>\n.item-form-page {\n  padding: 12px;\n  padding-bottom: 30px;\n}\n\n.item-form {\n  margin-top: 8px;\n}\n\n.photo-section {\n  margin-top: 4px;\n}\n\n.photo-list {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.photo-item {\n  position: relative;\n  width: 80px;\n  height: 80px;\n}\n\n.photo-item img {\n  width: 80px;\n  height: 80px;\n  object-fit: cover;\n  border-radius: 8px;\n  border: 1px solid var(--border-color);\n}\n\n.photo-del {\n  position: absolute;\n  top: -6px;\n  right: -6px;\n  width: 20px;\n  height: 20px;\n  border-radius: 50%;\n  background-color: var(--danger);\n  color: white;\n  font-size: 14px;\n  line-height: 20px;\n  text-align: center;\n  cursor: pointer;\n}\n\n.photo-add {\n  width: 80px;\n  height: 80px;\n  border: 2px dashed var(--border-color);\n  border-radius: 8px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  font-size: 12px;\n  color: var(--text-placeholder);\n  transition: border-color 0.2s;\n}\n\n.photo-add:hover {\n  border-color: var(--accent);\n  color: var(--accent);\n}\n\n.delete-section {\n  margin-top: 30px;\n}\n\n.photo-source-btns {\n  display: flex;\n  flex-direction: column;\n}\n</style>\n"],"sourceRoot":""}]);
